spec.setup_code:
var group = new api.THREE.Group();
                var sig = [true, true, true, false];
                for (var i = 0; i < sig.length; i++) {
                  var color = sig[i] ? 0x2E86AB : 0xCBD5E1;
                  var block = new api.THREE.Mesh(
                    new api.THREE.BoxGeometry(0.3, 0.3, 0.3),
                    new api.THREE.MeshPhongMaterial({ color: color })
                  );
                  block.position.x = (i - (sig.length - 1) / 2) * 0.4;
                  group.add(block);
                }
                api.group.add(group);
                return {
                  update: function(t) {
                    group.rotation.y = t * 0.02;
                  }
                };

return {
                  draw: function(ctx, W, H, t, dt) {
                    ctx.fillStyle = '#F5F0E8';
                    ctx.fillRect(0, 0, W, H);
                    var digits = ['0', '.', '0', '0', '2', '5'];
                    var sig = [false, false, false, false, true, true];
                    var startX = W / 2 - (digits.length * 30) / 2;
                    var cy = H / 2;
                    var glow = 0.5 + 0.5 * Math.sin(t * 0.08);
                    ctx.font = 'bold 36px sans-serif';
                    ctx.textAlign = 'center';
                    for (var i = 0; i < digits.length; i++) {
                      var x = startX + i * 30 + 15;
                      ctx.fillStyle = sig[i] ? ('rgba(232, 89, 60,' + (0.6 + 0.4 * glow) + ')') : '#94A3B8';
                      ctx.fillText(digits[i], x, cy);
                    }
                  }
                };

return {
                  draw: function(ctx, W, H) {
                    ctx.fillStyle = '#F9FAFB';
                    ctx.fillRect(0, 0, W, H);
                    var zeros = controls.zeros !== undefined ? controls.zeros : 1;
                    var hasDecimal = controls.hasDecimal !== undefined ? controls.hasDecimal : true;
                    var text = '1' + '0'.repeat(2) + (hasDecimal ? ('.' + '0'.repeat(zeros)) : '');
                    var sigFigs = hasDecimal ? (3 + zeros) : 1;
                    ctx.fillStyle = '#111827';
                    ctx.font = 'bold 40px sans-serif';
                    ctx.textAlign = 'center';
                    ctx.fillText(text, W / 2, H / 2 - 10);
                    ctx.font = '16px sans-serif';
                    ctx.fillStyle = '#2E86AB';
                    ctx.fillText('Significant figures: ' + sigFigs, W / 2, H / 2 + 40);
                  }
                };
